1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Rejects a create-owner request that would land in a household that already exists. The household
11	 * is keyed on {@code (lastName, postcode)} through the deterministic {@code householdId} assigned by
12	 * {@link AssignHousehold}, so a second owner sharing an existing owner's last name and postcode is a
13	 * household duplicate and is rejected with 409 (see {@link DuplicateIdentityException}).
14	 *
15	 * <p>A request may opt in with {@code sharesHousehold=true} to declare that it intentionally joins
16	 * that household. Doing so <em>bypasses this block</em> — the owner is created as a declared
17	 * household member — so {@code sharesHousehold} now only lifts the duplicate rejection rather than
18	 * creating the link (the link is implicit in the shared {@code householdId}).
19	 *
20	 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold} so the new owner's {@code householdId}
21	 * is already assigned, and before {@link SaveOwner} so the new owner is not compared against itself.
22	 */
23	public class CheckUniqueIdentity {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
26	            throws DuplicateIdentityException {
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return; // declared household member: bypass the duplicate block.
29	        }
30	        String householdId = owner.getHouseholdId();
31	        if (householdId == null || householdId.isBlank()) {
32	            return;
33	        }
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
36	                continue; // never collide with self (should not yet be persisted, but be safe)
37	            }
38	            if (householdId.equals(existing.getHouseholdId())) {
39	                throw new DuplicateIdentityException(householdId);
40	            }
41	        }
42	    }
43	}
